110	    /**
111	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
112	     * statement (not while PENDING), else the live due; null when it has none.
113	     */
114	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
115	        if (isFrozen(claim)) {
116	            return claim.getSettledDue();
117	        }
118	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
119	                : due(sheetId, person, claim);
120	    }
121	
122	    /** Whether the claim's figure is the due fixed when settled: SETTLED, or VOID once settled. */
123	    private static boolean isFrozen(Claim claim) {
124	        return claim.getStatus() == ClaimStatus.SETTLED
125	                || (claim.getStatus() == ClaimStatus.VOID && claim.getSettledDue() != null);
126	    }
127	
128	    /**
129	     * A claim's due on the sheet's today: the due fixed when settled, else its figure with its late
130	     * charge added on top, raised to the floor (see {@link LateCharge}); null when it has none.
131	     */
132	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
133	        if (isFrozen(claim)) {
134	            return claim.getSettledDue();
135	        }
136	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, person.gradeOn(claim.getDate()), figure(sheetId, person, claim));
137	    }
138	
139	    /**
140	     * A claim's due-by, fixed at creation: its date plus the first of the person's own terms, the
141	     * terms of their grade and the sheet's terms, each as in force on its date, counted in business
142	     * days: skipping every Saturday, Sunday and holiday on the sheet.
143	     */
144	    private LocalDate dueBy(String sheetId, LocalDate dated, int terms) {
145	        return holidays.businessDaysAfter(sheetId, dated, terms);
146	    }
147	
148	    /** The terms a claim of the person dated so is due by: their own, else those of their grade or the sheet. */
149	    private int terms(String sheetId, Person person, LocalDate dated) {
150	        Integer own = person.getTerms();
151	        return own != null ? own : sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated);
152	    }
