159	    @Transactional
160	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
161	            String corrects, String ref, List<String> tags) {
162	        roles.refuseViewer(sheetId, user);
163	        Person person = person(sheetId, personId);
164	        LocalDate dated = dateOrToday(sheetId, date);
165	        int terms = terms(sheetId, person, dated);
166	        LocalDate dueBy = dueBy(sheetId, dated, terms);
167	        periods.refuseIfClosed(sheetId, dueBy);
168	        refuseIfRetired(person, dated);
169	        String corrected = corrected(sheetId, personId, amount, corrects);
170	        refuseIfRefUsed(sheetId, ref, null);
171	        RollupService.Snapshot before = rollup.snapshot(sheetId);
172	        Claim claim = new Claim(sheetId, personId, amount, dated, dueBy, terms, note, corrected);
173	        claim.setRef(ref);
174	        claim.setTags(tags);
175	        claim.setLateEntry(periods.isSoftClosed(sheetId, dueBy));
176	        logStatus(sheetId, user, person, claim);
177	        Claim added = claims.saveAndFlush(claim);
178	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added)
179	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
180	                + (added.getTags().isEmpty() ? "" : " tags=" + String.join(",", added.getTags())));
181	        useTags(sheetId, added);
182	        if (added.isLateEntry()) {
183	            audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, added));
184	        }
185	        rollup.recordChanges(sheetId, user, before);
186	        return added;
187	    }
