189	    @Transactional
190	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
191	            String corrects, String ref, List<String> tags) {
192	        roles.refuseViewer(sheetId, user);
193	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
194	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
195	        refuseIfNotEditable(sheetId, user, claim);
196	        LocalDate dated = dateOrToday(sheetId, date);
197	        periods.refuseIfClosed(sheetId, claim.getDueBy());
198	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
199	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
200	        refuseIfRefUsed(sheetId, ref, claim.getId());
201	        RollupService.Snapshot before = rollup.snapshot(sheetId);
202	        claim.setAmount(amount);
203	        claim.setRef(ref);
204	        claim.setTags(tags);
205	        claim.setDate(dated);
206	        claim.setNote(note);
207	        claim.setCorrects(corrected);
208	        claim.setLockedBy(null);
209	        claim.setEditedBy(user);
210	        Claim saved = claims.saveAndFlush(claim);
211	        useTags(sheetId, saved);
212	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
213	        rollup.recordChanges(sheetId, user, before);
214	        return saved;
215	    }
