217	    /**
218	     * Change a DRAFT claim's amount in its row, keeping its date, note and correction: refused
219	     * exactly as the claim form's save is, and recorded as CLAIM_EDITED as it is. An editor the
220	     * user has open on the claim stays open.
221	     */
222	    @Transactional
223	    public Claim updateAmount(String sheetId, String user, long id, BigDecimal amount) {
224	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
225	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
226	        String lockedBy = claim.getLockedBy();
227	        Claim saved = update(sheetId, user, id, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
228	                claim.getRef(), claim.getTags());
229	        saved.setLockedBy(lockedBy);
230	        return claims.saveAndFlush(saved);
231	    }
