233	    /**
234	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
235	     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
236	     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
237	     * claim takes no lock. Any other claim of the same person the user had locked is released.
238	     */
239	    @Transactional
240	    public Claim lock(String sheetId, String user, long id) {
241	        roles.refuseViewer(sheetId, user);
242	        // hold the sheet so two users cannot both take the lock
243	        sheets.lock(sheetId);
244	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
245	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
246	        refuseIfNotEditable(sheetId, user, claim);
247	        periods.refuseIfClosed(sheetId, claim.getDueBy());
248	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
249	            if (other.getId() != id && user.equals(other.getLockedBy())) {
250	                other.setLockedBy(null);
251	                claims.save(other);
252	            }
253	        }
254	        claim.setLockedBy(user);
255	        return claims.saveAndFlush(claim);
256	    }
257	
258	    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
259	    @Transactional
260	    public Claim unlock(String sheetId, String user, long id) {
261	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
263	        if (user.equals(claim.getLockedBy())) {
264	            claim.setLockedBy(null);
265	            claim = claims.saveAndFlush(claim);
266	        }
267	        return claim;
268	    }
