270	    /** Refuse (409) editing a claim that is not DRAFT, or that another user's open editor locks. */
271	    private static void refuseIfNotEditable(String sheetId, String user, Claim claim) {
272	        if (claim.getStatus() != ClaimStatus.DRAFT) {
273	            throw new ResponseStatusException(HttpStatus.CONFLICT,
274	                    "A " + claim.getStatus() + " claim cannot be edited.");
275	        }
276	        if (claim.isLockedAgainst(user)) {
277	            throw new ResponseStatusException(HttpStatus.CONFLICT,
278	                    "This claim is being edited by " + claim.getLockedBy() + ".");
279	        }
280	    }
