293	    /**
294	     * Void a claim, as {@link #changeStatus(String, String, long, ClaimStatus)}, with a reason from
295	     * the sheet's void reasons: while the sheet has any, a void without one of them is refused (422).
296	     */
297	    @Transactional
298	    public Claim voidClaim(String sheetId, String user, long id, String voidReason) {
