302	    /**
303	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
304	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
305	     * user who opened it.
306	     */
307	    @Transactional
308	    public Claim approve(String sheetId, String user, long id) {
309	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true, null);
310	    }
