312	    /**
313	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
314	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
315	     */
316	    @Transactional
317	    public Claim reject(String sheetId, String user, long id, String reason) {
318	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true, null);
319	    }
