321	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
322	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
323	            boolean review, String voidReason) {
324	        roles.refuseViewer(sheetId, user);
325	        if (!review) {
326	            roles.refuseUnlessPermitted(sheetId, user, switch (next) {
327	                case OPEN -> "open";
328	                case SETTLED -> "settle";
329	                case VOID -> "void";
330	                default -> throw new IllegalStateException();
331	            });
332	        }
333	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
334	        if (next == ClaimStatus.OPEN) {
335	            sheets.lock(sheetId);
336	        }
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
339	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
340	        ClaimStatus was = claim.getStatus();
341	        // only a steward's review moves a PENDING claim on, other than voiding it
342	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
343	            throw new ResponseStatusException(HttpStatus.CONFLICT,
344	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
345	        }
346	        periods.refuseIfClosed(sheetId, claim.getDueBy());
347	        boolean reversing = was == ClaimStatus.SETTLED;
348	        if (reversing) {
349	            refuseVoidSettled(sheetId, user, claim);
350	        }
351	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
352	            throw new ResponseStatusException(HttpStatus.CONFLICT,
353	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
354	        }
355	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
356	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
357	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
358	        }
359	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
360	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
361	                    "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
362	        }
363	        if (review && !isSteward(sheetId, user)) {
364	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
365	                    "Only a steward can approve or reject a PENDING claim.");
366	        }
367	        String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
368	        Person person = person(sheetId, claim.getPersonId());
369	        if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
370	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
371	                    "A claim due above the note threshold cannot be opened with an empty note.");
372	        }
373	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
374	        // PENDING claim's figure is live)
375	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
376	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, person, claim, settling)) {
377	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
378	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
379	                            + " without a proof.");
380	        }
381	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
382	            next = ClaimStatus.PENDING;
383	            settling = null;
384	        }
385	        claim.setStatus(next);
386	        if (next == ClaimStatus.OPEN && !review) {
387	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
388	            claim.setOpenedBy(user);
389	        } else if (next == ClaimStatus.SETTLED) {
390	            claim.setSettledDue(settling);
391	        } else if (next == ClaimStatus.VOID) {
392	            claim.setVoidReason(voidedWith);
393	        }
394	        logStatus(sheetId, user, person, claim);
395	        Claim saved = claims.saveAndFlush(claim);
396	        String event = switch (next) {
397	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
398	            case PENDING -> "CLAIM_PENDING";
399	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
400	            case VOID -> "CLAIM_VOIDED";
401	            case DRAFT -> throw new IllegalStateException();
402	        };
403	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
404	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
405	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
406	                + (reason != null ? " reason=" + reason : "")
407	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
408	                + (voidedWith != null ? " reason=" + voidedWith : ""));
409	        if (next == ClaimStatus.SETTLED) {
410	            notifyWatchers(sheetId, user, person, saved);
411	        }
412	        rollup.recordChanges(sheetId, user, before);
413	        return saved;
414	    }
