416	    /**
417	     * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
418	     * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
419	     */
420	    private void refuseVoidSettled(String sheetId, String user, Claim claim) {
421	        if (!isSteward(sheetId, user)) {
422	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
423	        }
424	        LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
425	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
426	        LocalDate today = sheets.today(sheetId);
427	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
428	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
429	                    + VOID_SETTLED_DAYS + " days of its settlement.");
430	        }
431	    }
