433	    /** Record a notice of the claim for each user watching its person, in the order they started watching. */
434	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
435	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
436	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUserName()
437	                    + " person=" + person.getName() + " number=" + claim.getNumber());
438	        }
