441	    /**
442	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
443	     * the claim counts in no total, is not overdue and cannot be settled; a statement it is bound
444	     * by stays as it is. Refused (409) for a claim that is not OPEN, (400) for a date
445	     * not after the sheet's today and (423) when dated inside a closed period.
446	     */
447	    @Transactional
448	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
449	        roles.refuseViewer(sheetId, user);
450	        RollupService.Snapshot before = rollup.snapshot(sheetId);
451	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
452	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
453	        if (claim.getStatus() != ClaimStatus.OPEN) {
454	            throw new ResponseStatusException(HttpStatus.CONFLICT,
455	                    "A " + claim.getStatus() + " claim cannot be deferred.");
456	        }
457	        if (!until.isAfter(sheets.today(sheetId))) {
458	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
459	                    "A claim can only be deferred to a date after the sheet's today.");
460	        }
461	        periods.refuseIfClosed(sheetId, claim.getDueBy());
462	        Person person = person(sheetId, claim.getPersonId());
463	        claim.setDeferredUntil(until, sheets.today(sheetId));
464	        Claim saved = claims.saveAndFlush(claim);
465	        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
466	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
467	        rollup.recordChanges(sheetId, user, before);
468	        return saved;
469	    }
