479	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
480	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
481	            throw new ResponseStatusException(HttpStatus.CONFLICT,
482	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
483	        }
484	        periods.refuseIfClosed(sheetId, claim.getDueBy());
485	        Person person = person(sheetId, claim.getPersonId());
486	        claim.addProof();
487	        Claim saved = claims.saveAndFlush(claim);
488	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved)
489	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " proofs=" + saved.getProofs());
490	        return saved;
491	    }
