539	    /**
540	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
541	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
542	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
543	     */
544	    @Transactional
545	    public Claim resettle(String sheetId, String user, long id) {
546	        roles.refuseViewer(sheetId, user);
547	        if (!isSteward(sheetId, user)) {
548	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
549	        }
550	        RollupService.Snapshot before = rollup.snapshot(sheetId);
551	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
552	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
553	        if (claim.getStatus() != ClaimStatus.SETTLED) {
554	            throw new ResponseStatusException(HttpStatus.CONFLICT,
555	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
556	        }
557	        periods.refuseIfClosed(sheetId, claim.getDueBy());
558	        Person person = person(sheetId, claim.getPersonId());
559	        BigDecimal old = claim.getSettledDue();
560	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, person.gradeOn(claim.getDate()), due(sheetId, person, claim));
561	        claim.setSettledDue(settling);
562	        logStatus(sheetId, user, person, claim);
563	        Claim saved = claims.saveAndFlush(claim);
564	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
565	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
566	                + " old=" + dueText(old) + " new=" + dueText(settling));
567	        notifyWatchers(sheetId, user, person, saved);
568	        rollup.recordChanges(sheetId, user, before);
569	        return saved;
570	    }
