572	    /**
573	     * Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed, and with it its period and
574	     * number, and a figure bound by a statement stays bound. Refused (403) for anyone but a steward,
575	     * (409) for a claim that is not OPEN or PENDING, (423) when due inside a closed period and (422)
576	     * for a date after its person's retirement date.
577	     */
578	    @Transactional
579	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
580	        roles.refuseViewer(sheetId, user);
581	        if (!isSteward(sheetId, user)) {
582	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
583	        }
584	        // lock the sheet's numbering before reading the claim, as opening one does
585	        sheets.lock(sheetId);
586	        RollupService.Snapshot before = rollup.snapshot(sheetId);
587	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
588	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
589	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
590	            throw new ResponseStatusException(HttpStatus.CONFLICT,
591	                    "A " + claim.getStatus() + " claim cannot be re-dated.");
592	        }
593	        LocalDate old = claim.getDate();
594	        periods.refuseIfClosed(sheetId, claim.getDueBy());
595	        Person person = person(sheetId, claim.getPersonId());
596	        refuseIfRetired(person, date);
597	        claim.setDate(date);
598	        Claim saved = claims.saveAndFlush(claim);
599	        audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
600	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
601	                + " old=" + old + " new=" + date);
602	        rollup.recordChanges(sheetId, user, before);
