606	    /**
607	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its date and,
608	     * unless a DRAFT (which has no number), takes the next number in the sequence it is numbered in
609	     * (its old number is never used again), is unbound from any statement (live again until its new person's next statement), and
610	     * is listed first under its new person. Refused (403) for a role the permission matrix does not allow, (409) for a SETTLED or VOID
611	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
612	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
613	     * the new person's retirement date.
614	     */
615	    @Transactional
616	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
617	        return reassign(sheetId, user, id, toPersonId, false);
618	    }
