620	    private Claim reassign(String sheetId, String user, long id, long toPersonId, boolean allowSamePerson) {
621	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
622	        // lock the sheet's numbering before reading the claim, as opening one does
623	        sheets.lock(sheetId);
624	        RollupService.Snapshot before = rollup.snapshot(sheetId);
625	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
626	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
627	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
628	            throw new ResponseStatusException(HttpStatus.CONFLICT,
629	                    "A " + claim.getStatus() + " claim cannot be moved.");
630	        }
631	        Person from = person(sheetId, claim.getPersonId());
632	        Person to = person(sheetId, toPersonId);
633	        if (!allowSamePerson && from.getId().equals(to.getId())) {
634	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
635	        }
636	        if (claim.isCorrection()) {
637	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
638	        }
639	        periods.refuseIfClosed(sheetId, claim.getDueBy());
640	        refuseIfRetired(to, claim.getDate());
641	        // a numbered claim moved to another person takes the next number; its old one is not reused
642	        if (claim.getNumber() != null && !from.getId().equals(to.getId())) {
643	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
644	        }
645	        claim.setPersonId(to.getId());
646	        claim.bind(false, null);
647	        claims.saveAndFlush(claim);
648	        claims.listFirst(claim.getId());
649	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
650	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
651	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
652	                + " from=" + from.getName() + " to=" + to.getName());
653	        rollup.recordChanges(sheetId, user, before);
654	        return saved;
655	    }
