661	    /**
662	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
663	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
664	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
665	     * under the person and shows the original's number as split-from. Refused (403) for a role that
666	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
667	     * not above 0.00 and below the claim's, and (423) when the original is due inside a closed period
668	     * (the split's own due-by is not checked). The split is numbered in, and a late entry of, the
669	     * period of its own due-by.
670	     */
671	    @Transactional
672	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
673	        roles.refuseViewer(sheetId, user);
674	        roles.refuseUnlessPermitted(sheetId, user, "open");
675	        // lock the sheet's numbering before reading the claim, as opening one does
676	        sheets.lock(sheetId);
677	        RollupService.Snapshot before = rollup.snapshot(sheetId);
678	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
679	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
680	        if (claim.getStatus() != ClaimStatus.OPEN) {
681	            throw new ResponseStatusException(HttpStatus.CONFLICT,
682	                    "A " + claim.getStatus() + " claim cannot be split.");
683	        }
684	        if (claim.isDeferredOn(sheets.today(sheetId))) {
685	            throw new ResponseStatusException(HttpStatus.CONFLICT,
686	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
687	        }
688	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
689	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
690	                    "A split must be more than 0.00 and less than the claim's amount.");
691	        }
692	        periods.refuseIfClosed(sheetId, claim.getDueBy());
693	        Person person = person(sheetId, claim.getPersonId());
694	        claim.setAmount(claim.getAmount().subtract(amount));
695	        claim.bind(false, null);
696	        Claim original = claims.saveAndFlush(claim);
697	        LocalDate dated = claim.getDate();
698	        int terms = terms(sheetId, person, dated);
699	        Claim split = new Claim(sheetId, person.getId(), amount, dated, dueBy(sheetId, dated, terms), terms,
700	                claim.getNote(), null);
701	        split.setStatus(ClaimStatus.OPEN);
702	        split.setNumber(sheets.nextClaimNumber(sheetId, split.getDueBy()));
703	        split.setLateEntry(periods.isSoftClosed(sheetId, split.getDueBy()));
704	        split.setOpenedBy(user);
705	        split.setSplitFrom(original.getNumber());
706	        split.setTags(original.getTags());
707	        logStatus(sheetId, user, person, split);
708	        Claim added = claims.saveAndFlush(split);
709	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
710	                + " number=" + original.getNumber() + " into=" + added.getNumber());
711	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
712	        rollup.recordChanges(sheetId, user, before);
713	        return new Split(original, added);
714	    }
