720	    /**
721	     * Open the given claims together, in list order (the order people were added, newest claim
722	     * first within a person), so they are numbered in that order. A claim that cannot be opened
723	     * (not on the sheet, not DRAFT, dated inside a closed period, or due above the note threshold
724	     * with an empty note) is refused and left as it is.
725	     */
726	    @Transactional
727	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
728	        List<Claim> selected = inListOrder(sheetId, ids);
729	        int refused = (int) ids.stream().distinct().count() - selected.size();
730	        List<Claim> opened = new ArrayList<>();
731	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
732	        for (Claim claim : selected) {
733	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDueBy())
734	                    || needsNote(sheetId, person(sheetId, claim.getPersonId()), claim)) {
735	                refused++;
736	                continue;
737	            }
738	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
739	        }
740	        return new BulkOpened(opened.size(), refused, opened);
741	    }
