743	    /**
744	     * What a bulk settle did: how many claims were settled (or made PENDING) and how many refused,
745	     * the claims changed, and the sheet's last batch number after it (0 when there has been none).
746	     */
747	    public record BulkSettled(int settled, int refused, List<Claim> claims, int lastBatch) {
748	    }
749	
750	    /**
751	     * Settle the given claims together, all or nothing: in list order (the order people were added,
752	     * newest claim first within a person), each by exactly the rules of settling one claim. A claim
753	     * a clerk's settle makes PENDING counts as settled. When any selected claim cannot be settled
754	     * (or is not on the sheet), none is: every one counts as refused and nothing is written. Else the
755	     * settle is a batch: it takes the sheet's next batch number, each claim is marked with it, and
756	     * after the claims' own records one BATCH_SETTLED record gives the batch, its count and the
757	     * frozen dues of those SETTLED added up.
758	     */
759	    @Transactional
760	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
761	        List<Claim> selected = inListOrder(sheetId, ids);
762	        int requested = (int) ids.stream().distinct().count();
763	        List<Claim> settled = new ArrayList<>();
764	        boolean refusedAny = selected.size() < requested;
765	        for (Claim claim : selected) {
766	            if (refusedAny) {
767	                break;
768	            }
769	            try {
770	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
771	            } catch (ResponseStatusException refusedOne) {
772	                refusedAny = true;
773	            }
774	        }
775	        if (refusedAny || settled.isEmpty()) {
776	            // undo the claims already settled, and the records waiting for the commit with them
777	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
778	            return new BulkSettled(0, requested, List.of(), sheets.sheet(sheetId).getLastBatch());
779	        }
780	        int batch = sheets.nextBatch(sheetId);
781	        List<Claim> batched = new ArrayList<>();
782	        BigDecimal total = BigDecimal.ZERO;
783	        for (Claim claim : settled) {
784	            claim.setBatch(batch);
785	            batched.add(claims.saveAndFlush(claim));
786	            if (claim.getStatus() == ClaimStatus.SETTLED) {
787	                total = total.add(claim.getSettledDue());
788	            }
789	        }
790	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
791	                + " count=" + batched.size() + " total=" + dueText(total));
792	        return new BulkSettled(batched.size(), 0, batched, batch);
793	    }
