799	    /**
800	     * Move the given claims to one person together, in list order (the order people were added,
801	     * newest claim first within a person), each by exactly the rules of moving one claim. A claim
802	     * already on that person is moved in place (listed first, unbound). A claim that cannot be
803	     * moved is refused and left as it is.
804	     */
805	    @Transactional
806	    public BulkReassigned bulkReassign(String sheetId, String user, Collection<Long> ids, long toPersonId) {
807	        List<Claim> selected = inListOrder(sheetId, ids);
808	        int refused = (int) ids.stream().distinct().count() - selected.size();
809	        List<Claim> moved = new ArrayList<>();
810	        for (Claim claim : selected) {
811	            try {
812	                moved.add(reassign(sheetId, user, claim.getId(), toPersonId, true));
813	            } catch (ResponseStatusException refusedOne) {
814	                // every refusal is checked before the claim is changed, so it is left as it is
815	                refused++;
816	            }
817	        }
818	        return new BulkReassigned(moved.size(), refused, moved);
819	    }
