821	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
822	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
823	        Map<Long, Integer> personOrder = new HashMap<>();
824	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
825	        for (int i = 0; i < listed.size(); i++) {
826	            personOrder.put(listed.get(i).getId(), i);
827	        }
828	        return ids.stream().distinct()
829	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
830	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
831	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
832	                .toList();
833	    }
