835	    /**
836	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date
837	     * (the sheet's own, else its nearest ancestor's: see {@link RateChain}),
838	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
839	     * null with no rate in force then.
840	     */
841	    public BigDecimal due(String sheetId, Person person, Claim claim) {
842	        Sheet sheet = sheets.sheet(sheetId);
843	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
844	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
845	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
846	                .orElse(null);
847	    }
