849	    /** What a candidate rate would change: how many claims would show a different due, and the sum of new minus current. */
850	    public record RatePreview(int count, BigDecimal diff) {
851	    }
852	
853	    /**
854	     * Preview a candidate rate for a grade, as if it applied to that grade on every date: of the
855	     * OPEN and PENDING claims whose person has the grade on the claim's date, how many would show a
856	     * different due and the sum of the differences (new due minus current due). A claim bound by a
857	     * statement keeps its figure; a claim with no due counts as 0.00. Nothing is saved.
858	     */
859	    @Transactional(readOnly = true)
860	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
861	        Sheet sheet = sheets.sheet(sheetId);
862	        Map<Long, Person> byId = new HashMap<>();
863	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
864	            byId.put(p.getId(), p);
865	        }
866	        int count = 0;
867	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
868	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
869	            Person person = byId.get(claim.getPersonId());
870	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
871	                continue;
872	            }
873	            if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) {
874	                continue;
875	            }
876	            BigDecimal current = charged(sheetId, person, claim);
877	            RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
878	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
879	            BigDecimal next = LateCharge.withCharge(sheet, claim, grade, figure);
880	            BigDecimal was = current == null ? BigDecimal.ZERO : current;
881	            if (current == null || was.compareTo(next) != 0) {
882	                count++;
883	                diff = diff.add(next.subtract(was));
884	            }
885	        }
886	        return new RatePreview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
887	    }
