916	    /** Whether a claim's due is above the note threshold in force on its date and its note is empty. */
917	    private boolean needsNote(String sheetId, Person person, Claim claim) {
918	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
919	            return false;
